// Genera todas las combinaciones rubro×zona a partir de la config.
// Devuelve un array de items, uno por cada par (rubro, zona).

const config = $input.first().json;
const items = [];

for (const rubro of config.rubros || []) {
  for (const zona of config.zonas || []) {
    items.push({
      json: {
        rubro: rubro.nombre,
        zona: zona.nombre,
        provincia: zona.provincia,
        prioridad_zona: zona.prioridad,
        apify_searchTerm: rubro.apify_searchTerms_template
          .replace('{zona}', zona.nombre),
        instagram_hashtags: (rubro.instagram_hashtags_template || [])
          .map(h => h.replace('{zona_limpio}', zona.nombre.toLowerCase().replace(/\s+/g, ''))),
        pitch_default: rubro.pitch_default,
        config_completa: config
      }
    });
  }
}

return items;

// Convierte el HTML de Páginas Amarillas a leads estructurados
const html = $input.first().json.data || '';
const leads = [];

// Patrones de Páginas Amarillas AR (pueden cambiar, mantener actualizado)
const nombreMatches = [...html.matchAll(/<a[^>]*class="[^"]*business-name[^"]*"[^>]*>([^<]+)<\/a>/g)];
const dirMatches = [...html.matchAll(/<span[^>]*class="[^"]*address[^"]*"[^>]*>([^<]+)<\/span>/g)];
const telMatches = [...html.matchAll(/data-phone="([^"]+)"/g)];

for (let i = 0; i < Math.min(nombreMatches.length, 20); i++) {
  const nombre = nombreMatches[i][1].trim();
  if (nombre.length < 3) continue;
  leads.push({
    nombre,
    direccion: dirMatches[i] ? dirMatches[i][1].trim() : null,
    telefono: telMatches[i] ? telMatches[i][1].trim() : null,
    fuente: 'directorio_ar',
    webUrl: null
  });
}

return leads.length > 0 ? leads.map(l => ({ json: l })) : [{ json: { skip: true, fuente: 'directorio_ar' } }];

// Normaliza los leads que vienen de Google Maps (Apify)
// Input: array de lugares de Google Maps
const items = $input.all();
const leads = [];

for (const item of items) {
  const p = item.json;

  // Saltar si no tiene nombre o si es un resultado vacío
  if (!p.title || p.title.length < 3) continue;

  // Construir WhatsApp E.164 desde phone
  let whatsapp = null;
  if (p.phone) {
    const digits = p.phone.replace(/\D/g, '');
    if (digits.startsWith('54')) {
      whatsapp = digits;
    } else if (digits.length === 10 && digits.startsWith('0')) {
      whatsapp = '549' + digits.substring(1);
    } else if (digits.length === 10) {
      whatsapp = '549' + digits;
    } else if (digits.length === 8 || digits.length === 7) {
      whatsapp = '54935' + digits; // asumir Córdoba
    }
  }

  leads.push({
    json: {
      nombre: p.title,
      rubro: $('Generar Combinaciones Rubro×Zona').item.json.rubro,
      zona: $('Generar Combinaciones Rubro×Zona').item.json.zona,
      direccion: p.address || p.location?.address || null,
      telefono: p.phone || null,
      whatsapp,
      email: p.email || null,
      webUrl: p.website || null,
      redesSociales: [
        p.facebook ? `FB: ${p.facebook}` : null,
        p.instagram ? `IG: ${p.instagram}` : null,
        p.twitter ? `TW: ${p.twitter}` : null
      ].filter(Boolean).join(' | ') || null,
      estadoWeb: null, // se infiere en el CRM
      prioridad: null,
      fuente: 'google_maps',
      notas: p.categoryName ? `Categoría Google: ${p.categoryName}` : null,
      pitchSugerido: $('Generar Combinaciones Rubro×Zona').item.json.pitch_default
    }
  });
}

return leads.length > 0 ? leads : [{ json: { skip: true, fuente: 'google_maps' } }];

// Convierte la respuesta del endpoint buscar-online del CRM
// a leads normalizados para el siguiente paso.
const resp = $input.first().json;
const rubro = $('Generar Combinaciones Rubro×Zona').item.json.rubro;
const zona = $('Generar Combinaciones Rubro×Zona').item.json.zona;
const pitch = $('Generar Combinaciones Rubro×Zona').item.json.pitch_default;

// El endpoint ya creó los comercios en el CRM, pero igualmente
// los emitimos para que aparezcan en el reporte de Telegram.
const nuevos = resp.nuevos || [];

if (nuevos.length === 0) {
  return [{ json: { skip: true, fuente: 'web_search' } }];
}

// Como los leads ya se guardaron en el CRM (via el endpoint interno),
// acá solo armamos el objeto para el reporte de Telegram.
return nuevos.map(n => ({
  json: {
    id_crm: n.id,
    nombre: n.nombre,
    rubro,
    zona,
    webUrl: n.webUrl || null,
    fuente: 'web_search',
    ya_en_crm: true,
    pitchSugerido: pitch
  }
}));

// Convierte resultados de Instagram (posts por hashtag) en leads.
// Cada post puede pertenecer a un comercio diferente — agrupamos por ownerUsername.
const items = $input.all();
const rubro = $('Generar Combinaciones Rubro×Zona').item.json.rubro;
const zona = $('Generar Combinaciones Rubro×Zona').item.json.zona;
const pitch = $('Generar Combinaciones Rubro×Zona').item.json.pitch_default;

const comerciosPorOwner = {};
for (const item of items) {
  const p = item.json;
  const owner = p.ownerUsername || p.shortCode;
  if (!owner) continue;
  if (!comerciosPorOwner[owner]) {
    comerciosPorOwner[owner] = {
      nombre: p.ownerUsername || owner,
      rubro,
      zona,
      direccion: null,
      telefono: null,
      whatsapp: null,
      email: null,
      webUrl: p.url || null,
      redesSociales: `IG: @${p.ownerUsername}`,
      estadoWeb: 'Sin web (solo red social)',
      prioridad: 'Alta',
      fuente: 'instagram',
      notas: `Hashtag: ${p.hashtag || 'n/a'}, ${p.likes || 0} likes en último post`,
      pitchSugerido: pitch
    };
  }
}

const leads = Object.values(comerciosPorOwner);
return leads.length > 0 ? leads.map(l => ({ json: l })) : [{ json: { skip: true, fuente: 'instagram' } }];

// Convierte páginas de Facebook scrapeadas a leads.
const items = $input.all();
const rubro = $('Generar Combinaciones Rubro×Zona').item.json.rubro;
const zona = $('Generar Combinaciones Rubro×Zona').item.json.zona;
const pitch = $('Generar Combinaciones Rubro×Zona').item.json.pitch_default;

const leads = [];
for (const item of items) {
  const p = item.json;
  if (!p.name || p.name.length < 3) continue;

  leads.push({
    json: {
      nombre: p.name,
      rubro,
      zona,
      direccion: p.address || p.location?.street || null,
      telefono: p.phone || null,
      whatsapp: p.phone ? p.phone.replace(/\D/g, '') : null,
      email: p.email || null,
      webUrl: p.website || null,
      redesSociales: `FB: ${p.name}${p.instagram ? ' | IG: ' + p.instagram : ''}`,
      estadoWeb: p.website ? null : 'Sin web (solo red social)',
      prioridad: p.website ? null : 'Alta',
      fuente: 'facebook',
      notas: p.about ? `About: ${p.about.substring(0, 200)}` : null,
      pitchSugerido: pitch
    }
  });
}

return leads.length > 0 ? leads : [{ json: { skip: true, fuente: 'facebook' } }];

// Filtra leads inválidos y aplica las reglas de calidad de la config.
// También dedupliquea dentro del mismo lote (por nombre normalizado).
const items = $input.all();
const config = $('Generar Combinaciones Rubro×Zona').item.json.config_completa;
const filtro = config.filtro_calidad || {};
const excluirNombres = (filtro.excluir_nombres || []).map(s => s.toLowerCase());
const excluirDominios = (filtro.excluir_dominios || []).map(s => s.toLowerCase());

function normalizeName(s) {
  return (s || '').toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]/g, '').trim();
}

const vistos = new Set();
const leads = [];

for (const item of items) {
  const l = item.json;
  if (l.skip) continue;
  if (!l.nombre || l.nombre.length < 3) continue;

  const nombreLower = l.nombre.toLowerCase();
  if (excluirNombres.some(ex => nombreLower.includes(ex))) continue;

  if (l.webUrl) {
    const hostMatch = l.webUrl.toLowerCase().match(/https?:\/\/([^/]+)/);
    if (hostMatch) {
      const host = hostMatch[1];
      if (excluirDominios.some(ex => host.includes(ex))) continue;
    }
  }

  const key = `${normalizeName(l.nombre)}|${l.zona}`;
  if (vistos.has(key)) continue;
  vistos.add(key);

  leads.push({ json: l });
}

return leads.length > 0 ? leads : [{ json: { _no_leads: true } }];

// Construye el mensaje enriquecido para Telegram y filtra solo prioridad Alta
const items = $input.all();
const config = $('Cargar Config Rubros/Zonas').item.json;
const prioridadFiltro = config.telegram.notificar_solo_prioridad || ['Alta'];

const leadsFiltrados = items.filter(item => {
  const c = item.json.comercio || item.json;
  if (!c) return false;
  if (item.json.created === false) return false; // duplicado
  return prioridadFiltro.includes(c.prioridad || 'Alta');
});

if (leadsFiltrados.length === 0) {
  return [{ json: { _sin_leads_alta: true, total_leads: items.length } }];
}

const fecha = new Date().toLocaleDateString('es-AR', { day: '2-digit', month: '2-digit', year: 'numeric' });

// Mensaje inicial
let mensaje = config.telegram.mensaje_inicial
  .replace('{total}', leadsFiltrados.length)
  .replace('{fecha}', fecha) + '\n\n';

// Generar un item por cada lead con su mensaje formateado
const mensajes = [];
for (const item of leadsFiltrados) {
  const c = item.json.comercio || item.json;

  // WhatsApp deep link
  let waLink = '';
  if (c.whatsapp) {
    const texto = encodeURIComponent(`Hola ${c.nombre}, vi tu negocio y me gustaría proponerte algo. Soy Gonzalo de Paulero Studio.`);
    waLink = `https://wa.me/${c.whatsapp}?text=${texto}`;
  } else if (c.telefono) {
    const digits = (c.telefono || '').replace(/\D/g, '');
    if (digits.length > 6) {
      const texto = encodeURIComponent(`Hola ${c.nombre}, vi tu negocio y me gustaría proponerte algo. Soy Gonzalo de Paulero Studio.`);
      waLink = `https://wa.me/${digits.length === 10 ? '549' + digits : digits}?text=${texto}`;
    }
  }

  // CRM deep link (asumiendo que el CRM tiene una URL /comercio/{id})
  const crmLink = `${$env.CRM_BASE_URL || 'http://localhost:3000'}/?comercio=${c.id}`;

  const emoji = c.prioridad === 'Alta' ? '🔥' : c.prioridad === 'Media' ? '🟡' : '⚪';

  const leadMsg = `${emoji} <b>${c.nombre}</b>
` +
    `📍 ${c.rubro} en ${c.zona}\n` +
    (c.direccion ? `🏠 ${c.direccion}\n` : '') +
    (c.telefono ? `📞 ${c.telefono}\n` : '') +
    (c.webUrl ? `🌐 ${c.webUrl}\n` : '') +
    (c.estadoWeb ? `📊 Web: ${c.estadoWeb}\n` : '') +
    (c.redesSociales ? `📱 ${c.redesSociales}\n` : '') +
    (c.notas ? `📝 ${c.notas.substring(0, 120)}${c.notas.length > 120 ? '…' : ''}\n` : '') +
    `🏷️ Fuente: ${item.json.comercio?.notas?.match(/Fuente: ([^|]+)/)?.[1]?.trim() || 'n8n'}\n` +
    (c.pitchSugerido ? `💬 <i>Pitch:</i> ${c.pitchSugerido}\n` : '') +
    (waLink ? `\n🟢 <a href=\"${waLink}\">Abrir WhatsApp</a>` : '⚠️ Sin WhatsApp') +
    ` | <a href=\"${crmLink}\">Ver en CRM</a>`;

  mensajes.push({ json: { mensaje: leadMsg, lead: c, waLink, crmLink } });
}

// El primer item lleva el encabezado
if (mensajes.length > 0) {
  mensajes[0].json.mensaje = mensaje + mensajes[0].json.mensaje;
}

return mensajes;
